cli: ork docs init, .markdownlint-cli2.j:
// Padronizacao de Markdown da documentacao de produto e do roadmap (Orkastery, I-44).
// Divisao de trabalho: este linter cobre a FORMA do Markdown; `ork docs verificar` cobre
// frontmatter, leitura (TDAH), paridade com o codigo e com o git.
{
  "globs": [
    "docs/produto/**/*.md",
    "docs/roadmap/**/*.md",
    "docs/padroes/**/*.md",
    "README.md"
  ],
  "config": {
    "default": true,
    // Prosa em portugues nao quebra linha em 80 colunas: um paragrafo e uma linha.
    "MD013": false,
    // "Historico" e "Comportamento" repetem entre paginas, nunca entre irmaos do mesmo titulo.
    "MD024": { "siblings_only": true },
    // O modelo usa a mesma forma de lista ordenada que o padrao do dono.
    "MD029": { "style": "one_or_ordered" },
    // HTML so para imagem, selo e dobra de detalhe; layout em HTML esconde a resposta da primeira linha.
    "MD033": { "allowed_elements": ["img", "picture", "source", "br", "sub", "sup", "kbd", "details", "summary"] }
  }
}
